export const meta = {
  "slug": "tabler-key",
  "family": "tabler",
  "name": "key",
  "category": "Status",
  "motion": "lock",
  "component": "createTablerKeyIcon"
};

export function createTablerKeyIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
